R=C=19
G=[[0]*C for _ in range(R)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
# map plus arms owner and initialize input
arms={}
for (r,c),v in centers.items():
    G[r][c]=v
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        p=(r+dr,c+dc); G[p[0]][p[1]]=3; arms[p]=(r,c)
hollow=(10,8)
for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    p=(hollow[0]+dr,hollow[1]+dc); G[p[0]][p[1]]=3; arms[p]=hollow
orig=[row[:] for row in G]
# build horizontal/vertical rays from every center; foreign plus-arm cells stop that direction
H=[[0]*C for _ in range(R)]; V=[[0]*C for _ in range(R)]
for (r,c),v in centers.items():
    H[r][c]=v; V[r][c]=v
    for dr,dc,arr in [(0,-1,H),(0,1,H),(-1,0,V),(1,0,V)]:
        i,j=r+dr,c+dc
        while 0<=i<R and 0<=j<C:
            owner=arms.get((i,j))
            if orig[i][j]==3 and owner != (r,c): break
            arr[i][j]=v
            i+=dr;j+=dc
# compose, preserve all original crosses; vertical projections win horizontal overlaps
out=[row[:] for row in orig]
for i in range(R):
    for j in range(C):
        if orig[i][j]==3: continue
        if H[i][j]: out[i][j]=H[i][j]
        if V[i][j]: out[i][j]=V[i][j]
        if (i==hollow[0] or j==hollow[1]) and (H[i][j] or V[i][j]): out[i][j]=0
print('\n'.join(' '.join(map(str,row)) for row in out))

